+	}
+	r.Limit = initialStreamChunkLimit
+	if r.Limit > totalLimit {
+		r.Limit = totalLimit
+	}
+
+	count := int64(0)
+	var headerRev int64
+	for {
+		// gofail: var beforeRangeStreamChunk struct{}
+		resp, _, err := txn.Range(ctx, s.Logger(), s.KV(), r, false)
+		if err != nil {
+			return err
+		}
+		// Pin an implicit revision to the first chunk's store revision so writes
+		// committed after the stream begins are not reflected in later chunks.
+		if headerRev == 0 {
+			headerRev = resp.Header.Revision
+			if r.Revision == 0 {
